import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {SessionResumeOptions} from './ws/sessionResume.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ConnectedMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what a reconnect is sent is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  resumeFailure?: string;
  index?: number;
  entry?: SessionEntry;
}

const NEVER_ISSUED = '0f1e2d3c-4b5a-4968-8776-655443322110';
const RESUME_ON: SessionResumeOptions = {enabled: true};
const LATEST_ON: SessionResumeOptions = {enabled: true, latest: true};
const HALF_ANSWER: SessionEntry = {
  role: 'assistant',
  content: 'half',
  timestamp: '2026-09-30T08:00:01.000Z',
  isStreaming: true,
};

// A tool's suppression lands while the answer is still open, as when a provider ends a tool round with no stop.
const suppressingMidAnswer: ChatOrchestrator = {
  processMessage: async () => 'before after',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'before'};
    yield {type: 'suppress_output'} as unknown as MessageChunk;
    yield {type: 'text', text: ' after'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

// Silenced for the whole file: the server logs every connection and close, and these tests read frames, not logs.
beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

afterAll(() => {
  setLogger();
});

// Each server sees its sockets close before it stops, so no close is logged after the logger above is restored.
afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
});

// The authenticated user is read per upgrade, so one test can reconnect as someone else.
const startEngine = async (
  store: SessionStore,
  resume?: SessionResumeOptions,
  orchestrator: ChatOrchestrator = answeringOrchestrator
) => {
  const auth = {userId: 'u1'};
  const connects: Array<{sessionId: string; resumed: boolean}> = [];
  const disconnected: string[] = [];
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: auth.userId}),
    sessionStore: store,
    orchestrator,
    resume,
    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
    onDisconnect: sessionId => void disconnected.push(sessionId),
  });
  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
  const firstServerClose = new Promise<void>(resolve => {
    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string, token = 't'): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
};

// One question answered and the socket closed, returning the id the connected frame announced.
const firstTurn = async (base: string): Promise<string> => {
  const client = open(base);
  let sessionId = '';
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
      if (frame.type === 'stream_end') resolve();
    });
  });
  client.close();
  await once(client, 'close');
  return sessionId;
};

// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
  const client = open(url, token);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      frames.push(frame);
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      if (frame.type === 'pong') resolve();
    });
  });
  return frames;
};

const upserts = (frames: Frame[]) =>
  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));

const shapeOf = (frames: Frame[]) => ({
  keys: Object.keys(frames[0]).sort(),
  resumed: frames[0].resumed,
  resumeFailure: frames[0].resumeFailure,
  types: frames.map(frame => frame.type),
});

const deferredRelease = () => {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release: () => release()};
};

// Each stored conversation holds one user entry, sent at the given time and reading as its own id.
const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string]>): InMemorySessionStore => {
  const store = new InMemorySessionStore();
  for (const [sessionId, userId, sentAt] of conversations) {
    const {entries} = store.create(sessionId, userId);
    entries.push({role: 'user', content: sessionId, timestamp: sentAt});
  }
  return store;
};

// A store with only the required members, so an optional one can be added, replaced or left out per test.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('resuming a conversation on reconnect', () => {
  it('with resume absent, answers a reconnect naming the first id with a new id and no replay', async () => {
    const {base} = await startEngine(new InMemorySessionStore());
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    expect({newId: frames[0].sessionId !== first, shape: shapeOf(frames)}).toEqual({
      newId: true,
      shape: {
        keys: ['examplePrompts', 'message', 'sessionId', 'type'],
        resumed: undefined,
        types: ['connected', 'pong'],
      },
    });
  });

  it('with resume on, answers the owner reconnecting with resumed true, entryCount 2 and both stored entries', async () => {
    const store = new InMemorySessionStore();
    const {base} = await startEngine(store, RESUME_ON);
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    const stored = JSON.parse(JSON.stringify((await store.get(first))?.entries)) as SessionEntry[];
    expect({connected: frames[0], replay: upserts(frames)}).toMatchObject({
      connected: {type: 'connected', sessionId: first, resumed: true, entryCount: 2},
      replay: [
        {index: 0, entry: stored[0]},
        {index: 1, entry: stored[1]},
      ],
    });
#!/usr/bin/env node
// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
//
// Usage:
//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
//
// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
// it, and the citation silently lands on a different, still-valid declaration. The name is what the
// author meant, so the name is what the citation records and the line becomes a derived pointer this
// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
// citation without one marks the whole file covered rather than one test.
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import process from 'node:process';
import {dirname, join, normalize} from 'node:path';
import {root} from './lib/repo-root.mjs';

const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
// to the same file and counts them, while this gate and the drift check would never have read them.
const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;

const cache = new Map();
const args = process.argv.slice(2);
const fix = args.includes('--fix');
const named = args.filter(arg => !arg.startsWith('--'));
const findings = [];
let checked = 0;
let repaired = 0;

for (const spec of named.length > 0 ? named : specs()) {
  const source = readFileSync(join(root, spec), 'utf8');
  const specDir = dirname(spec);
  let changed = false;

  for (const match of source.matchAll(ANY_HREF)) {
    if (!match.groups.path.startsWith('../')) {
      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
    }
  }

  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
    const groups = rest[rest.length - 1];
    const target = normalize(join(specDir, groups.path));
    if (!TEST_FILE.test(target)) return whole;

    checked += 1;
    const declarations = declarationsIn(target);
    if (declarations === null) {
      findings.push(`${spec}: ${groups.path} does not exist`);
      return whole;
    }

    const named = groups.label ? groups.label.slice(2) : null;
    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));

    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
    if (skipped) {
      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
      return whole;
    }

    if (named === null) {
      if (!atLine) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
        return whole;
      }
      if (nameIsAmbiguous(declarations, atLine.name)) {
        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
        return whole;
      }
      if (!fix) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
        return whole;
      }
      return rewrite(atLine.name, groups.path, atLine.line);
    }

    // Checked before the line is consulted: a name that identifies two declarations is not an
    // identifier, and while the line happens to agree nothing would ever say so.
    if (nameIsAmbiguous(declarations, named)) {
      findings.push(ambiguity(spec, groups.path, named, declarations));
      return whole;
    }

    if (atLine && atLine.name === named) return whole;

    const [match] = declarations.filter(declaration => declaration.name === named);
    if (!match) {
      findings.push(`${spec}: names "${named}", which no declaration in ${groups.path} has`);
      return whole;
    }
    if (!fix) {
      findings.push(`${spec}: names "${named}" but points at #L${groups.line}; it is at #L${match.line}`);
      return whole;
    }
    return rewrite(named, groups.path, match.line);

    function rewrite(name, path, line) {
      // A name carrying a bracket would close the markdown label early: the citation stops being a
      // link, stops matching CITATION, and disappears from this gate and from the coverage job.
      if (/[[\]]/.test(name)) {
        findings.push(`${spec}: "${name}" carries a bracket and cannot be written into a markdown label`);
        return whole;
      }
      repaired += 1;
      changed = true;
      return citation(name, path, line);
    }
  });

  if (changed) writeFileSync(join(root, spec), rewritten);
}

for (const finding of findings) process.stderr.write(`check-spec-anchor-names: ${finding}\n`);

if (findings.length > 0) {
  process.stderr.write(`\ncheck-spec-anchor-names: ${findings.length} finding(s).\n`);
  process.stderr.write('Run `npm run spec:names -- --fix` to repoint a citation from the name it carries.\n');
  process.exit(1);
}

const verb = fix ? `repointed ${repaired},` : '';
process.stdout.write(`check-spec-anchor-names: ${verb} ${checked} citation(s) name the test they point at\n`);

function nameIsAmbiguous(declarations, name) {
  return declarations.filter(declaration => declaration.name === name && !declaration.skipped).length > 1;
}

function ambiguity(spec, path, name, declarations) {
  const lines = declarations.filter(declaration => declaration.name === name).map(d => `#L${d.line}`);
  return `${spec}: "${name}" names ${lines.length} declarations in ${path} (${lines.join(', ')}) — rename one`;
}

function citation(name, path, line) {
  return `[validated by: ${name}](${path}#L${line})`;
}

function declarationsIn(path) {
  if (cache.has(path)) return cache.get(path);

  let lines;
  try {
    lines = readFileSync(join(root, path), 'utf8').split('\n');
  } catch {
    cache.set(path, null);
    return null;
  }
  const found = lines.flatMap((text, index) => {
    const match = DECLARATION.exec(text);
    if (match) return [{line: index + 1, name: match[2], skipped: false}];
    const skipped = SKIPPED.exec(text);
    return skipped ? [{line: index + 1, name: skipped[2], skipped: true}] : [];
  });

  cache.set(path, found);
  return found;
}

function specs() {
  const out = execFileSync('git', ['ls-files', 'specs/**/*.md', 'adrs/*.md'], {cwd: root, encoding: 'utf8'});
  return out.trim().split('\n').filter(Boolean);
}
